import{_ as a,o,c as t,ae as i}from"./chunks/framework.YL6nI5ZP.js";const u=JSON.parse('{"title":"Cómo Ejecutar la Aplicación Localmente","description":"","frontmatter":{},"headers":[],"relativePath":"es/how-to/01-ejecutar-localmente.md","filePath":"es/how-to/01-ejecutar-localmente.md"}'),s={name:"es/how-to/01-ejecutar-localmente.md"};function r(l,e,n,c,d,p){return o(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="como-ejecutar-la-aplicacion-localmente" tabindex="-1">Cómo Ejecutar la Aplicación Localmente <a class="header-anchor" href="#como-ejecutar-la-aplicacion-localmente" aria-label="Permalink to &quot;Cómo Ejecutar la Aplicación Localmente&quot;">​</a></h1><p>Ejecuta la aplicación web Local SWMM en tu propio computador con el servidor estático de Python incluido, en lugar del sitio de producción.</p><h2 id="requisitos" tabindex="-1">Requisitos <a class="header-anchor" href="#requisitos" aria-label="Permalink to &quot;Requisitos&quot;">​</a></h2><ul><li>Python 3 y un navegador moderno. (Node solo se necesita para <code>npm install</code> y los scripts de tooling.)</li></ul><h2 id="_1-clona-el-repositorio" tabindex="-1">1. Clona el repositorio <a class="header-anchor" href="#_1-clona-el-repositorio" aria-label="Permalink to &quot;1. Clona el repositorio&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --branch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> experimental</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/JoaquinAlvarado-py/LocalSWMM.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> LocalSWMM</span></span></code></pre></div><h2 id="_2-inicia-el-servidor-web-local" tabindex="-1">2. Inicia el servidor web local <a class="header-anchor" href="#_2-inicia-el-servidor-web-local" aria-label="Permalink to &quot;2. Inicia el servidor web local&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server.py</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # serves ./public on http://127.0.0.1:8080</span></span></code></pre></div><h2 id="_3-abre-la-aplicacion" tabindex="-1">3. Abre la aplicación <a class="header-anchor" href="#_3-abre-la-aplicacion" aria-label="Permalink to &quot;3. Abre la aplicación&quot;">​</a></h2><p>Abre <strong><a href="http://127.0.0.1:8080" target="_blank" rel="noreferrer">http://127.0.0.1:8080</a></strong> en tu navegador web. Si el mapa base no carga, necesitas agregar tu token de Mapbox a <code>public/config.js</code> — consulta <a href="./02-configurar">Cómo Configurar Local SWMM</a>.</p><h2 id="_4-opcional-instala-el-tooling-de-js" tabindex="-1">4. (Opcional) Instala el tooling de JS <a class="header-anchor" href="#_4-opcional-instala-el-tooling-de-js" aria-label="Permalink to &quot;4. (Opcional) Instala el tooling de JS&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                # installs triangle-wasm (dev dependency, vendored copy)</span></span></code></pre></div><h2 id="_5-verifica-con-un-modelo-de-muestra" tabindex="-1">5. Verifica con un modelo de muestra <a class="header-anchor" href="#_5-verifica-con-un-modelo-de-muestra" aria-label="Permalink to &quot;5. Verifica con un modelo de muestra&quot;">​</a></h2><p>Carga <strong>Bellinge Web</strong> desde el menú desplegable <strong>Open Model ▾</strong> y luego pulsa <strong>Run</strong>. Esta es la red de referencia usada en toda la suite de pruebas.</p><h2 id="lo-que-hace-el-servidor" tabindex="-1">Lo que hace el servidor <a class="header-anchor" href="#lo-que-hace-el-servidor" aria-label="Permalink to &quot;Lo que hace el servidor&quot;">​</a></h2><p><code>server.py</code> es un servidor estático de cero dependencias (stdlib de Python):</p><table tabindex="0"><thead><tr><th>Aspecto</th><th>Valor</th></tr></thead><tbody><tr><td>Bind</td><td>solo <code>127.0.0.1</code></td></tr><tr><td>Puerto</td><td><strong>8080</strong></td></tr><tr><td>Raíz de documentos</td><td><code>&lt;repo&gt;/public</code></td></tr><tr><td>Endpoints</td><td><code>GET /api/status</code> → <code>{&quot;status&quot;:&quot;running&quot;,&quot;msg&quot;:&quot;3D Map Prototype Server Online&quot;}</code>; todo lo demás = GET estático</td></tr><tr><td>Headers</td><td><code>Cache-Control: no-store</code> (wasm/JS fresco en cada recarga)</td></tr><tr><td>CORS</td><td><code>Access-Control-Allow-Origin: *</code> en OPTIONS + <code>/api/status</code></td></tr><tr><td>Concurrencia</td><td><code>ThreadingTCPServer</code>, <code>daemon_threads=True</code></td></tr></tbody></table><p>El servidor envía los mismos headers <code>Cross-Origin-Opener-Policy: same-origin</code> / <code>Cross-Origin-Embedder-Policy: credentialless</code> que producción, por lo que el motor con threads (pthreads/<code>SharedArrayBuffer</code>) funciona en <code>http://127.0.0.1:8080</code> de inmediato.</p><h2 id="discrepancia-conocida" tabindex="-1">Discrepancia conocida <a class="header-anchor" href="#discrepancia-conocida" aria-label="Permalink to &quot;Discrepancia conocida&quot;">​</a></h2><blockquote><p>El README dice que el directorio del proyecto es <code>SWMM_3D_Web_UI</code> y que la URL es <code>http://localhost:8000</code>. El directorio real es <code>LocalSWMM</code> y el servidor escucha en el puerto <strong>8080</strong> (<code>server.py:6</code>). Usa los comandos de arriba.</p></blockquote>`,20)])])}const g=a(s,[["render",r]]);export{u as __pageData,g as default};
